 paragraphs=[(m.start(),m.group().strip()) for m in re.finditer(r'(?ms)(?<=\n\n).*?(?=\n\n|\Z)',src) if m.group().strip() and not m.group().strip().startswith(('<div','</div>','{{block:','#'))]
